// Section partials for the webdetector pages. Each card is defined ONCE
// here (previously every page carried byte-copies of every section and
// shouldShow() hid the dead ones at runtime - the copies had already
// started to diverge). Pages hold <div data-wd-section="name"></div>
// placeholders; expandPartials() inlines these strings BEFORE the Vue
// app mounts, so the markup compiles as part of the root template and
// keeps full access to root state - no component-scope plumbing.

// SIGNAL_LEGEND is the one "what does each pill mean" toolbox, inlined above the
// WebTop and Suspicious tables so the abuse-shadow signal names are explained in
// plain language WITHOUT having to hover each pill's tooltip. Defined ONCE and
// concatenated into both cards (never a second copy that can drift — CLAUDE.md
// §5). Collapsed by default; the summary keeps it discoverable and unobtrusive.
// The five pills below mirror the table pills exactly (same classes/labels).
const SIGNAL_LEGEND =
  "<details class=\"raw-json signal-legend\">" +
  "<summary>ℹ What the signal pills mean — all shadow / log-only (nothing here blocks yet)</summary>" +
  "<ul class=\"legend-list\">" +
  "<li><span class=\"pill info\">farm</span><span><strong>solver farm</strong> — a distributed challenge-solving farm on this vhost: many one-solve-per-address clients spread across distinct subnets. Alert-only.</span></li>" +
  "<li><span class=\"pill warn\">shadow N</span><span><strong>rate outlier</strong> — N source IP(s) doing many× the vhost's own median per-IP request rate (a concentrated scraper that hides under the vhost-aggregate score).</span></li>" +
  "<li><span class=\"pill warn\">facet N</span><span><strong>facet expansion</strong> — N distinct query-string URLs on very few base paths (a faceted-URL flood: <code>?filter=…</code>/<code>?sort=…</code> permutations that path_diversity cannot see).</span></li>" +
  "<li><span class=\"pill danger\">cost N%</span><span><strong>cost pressure</strong> — the origin is returning N% 5xx on this vhost (expensive requests driving origin collapse).</span></li>" +
  "<li><span class=\"pill info\">dc N%</span><span><strong>datacenter fraction</strong> — N% of this vhost's traffic is from unverified datacenter/cloud ASNs (verified crawlers like Googlebot excluded via FCrDNS). Corroborating only — never a decision on its own.</span></li>" +
  "</ul>" +
  "<p class=\"muted legend-foot\">All five are burn-in signals written to <code>cfm.abuse_shadow.log</code> and aggregated by the <code>abuse_shadow</code> tool; they measure only. The <span class=\"pill warn\">suspicious</span> / <span class=\"pill danger\">challenged</span> / <span class=\"pill attack\">🚨 under attack</span> pills are live status, not shadow signals.</p>" +
  "</details>";

export const PARTIALS = {
  topbar: "<header class=\"topbar\">\n      <button class=\"nav-burger\" type=\"button\" data-nav-burger aria-label=\"Toggle navigation\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M4 7h16M4 12h16M4 17h16\"/></svg></button>\n      <h1>{{ pageTitle }}</h1>\n      <div class=\"meta\">\n        <span class=\"muted\" v-if=\"lastRefreshLabel\">{{ lastRefreshLabel }}</span>\n        <span class=\"muted\">Auto-refresh: <strong>{{ autoRefresh ? 'ON' : 'OFF' }}</strong></span>\n        <label for=\"refresh-interval\" class=\"muted\">Every</label>\n        <input\n          id=\"refresh-interval\"\n          class=\"input input-small\"\n          type=\"number\"\n          min=\"1\"\n          max=\"300\"\n          step=\"1\"\n          v-model.number=\"refreshIntervalSec\"\n          @change=\"applyRefreshInterval\"\n        />\n        <span class=\"muted\">sec</span>\n        <button class=\"btn-quiet\" @click=\"refreshAll\" :disabled=\"loading\">{{ loading ? 'Refreshing...' : 'Refresh now' }}</button>\n        <button class=\"btn-quiet\" v-if=\"autoRefresh\" @click=\"stopAutoRefresh\">Stop</button>\n        <button class=\"btn-quiet\" v-else @click=\"startAutoRefresh\">Start</button>\n      </div>\n    </header>",
  pageheader: "<section class=\"card wide\">\n        <h2>{{ pageTitle }}</h2>\n        <p class=\"muted\">Use focused subpages to keep live monitoring separate from investigation workflows.</p>\n      </section>",
  pageheadervhost: "<section class=\"card wide\">\n        <h2>{{ pageTitle }}</h2>\n        <p class=\"muted\">One vhost: what applies to it, who visits it, what it costs, and the live drilldown.</p>\n        <div class=\"toolbar\">\n          <label for=\"vhost-focus-host\">Vhost</label>\n          <input id=\"vhost-focus-host\" class=\"input input-wide\" type=\"text\" v-model.trim=\"vhostFocusHost\" placeholder=\"example.com\" list=\"cfm-vhost-list\" />\n          <datalist id=\"cfm-vhost-list\"><option v-for=\"h in knownVhosts\" :key=\"h\" :value=\"h\"></option></datalist>\n          <button class=\"btn-quiet\" @click=\"applyVhostFocus\">Open</button>\n          <span class=\"muted\" v-if=\"activeHost\">Current: <strong>{{ activeHost }}</strong></span>\n        </div>\n      </section>",
  // Vhost page profile tabs (feature-vhost-profile.js); admin only.
  vhostprofile: "<template v-if=\"vpEnabled\">\n      <section class=\"card wide vp-head\" aria-labelledby=\"vp-host-title\">\n        <div class=\"vp-dom\">\n          <div>\n            <h2 id=\"vp-host-title\" class=\"vp-host\">{{ activeHost || \"No vhost selected\" }}</h2>\n            <p class=\"muted vp-sub\" v-if=\"vpProfile\">\n              <template v-if=\"vpProfile.site\">Domain <strong>{{ vpProfile.site }}</strong> \u00b7 {{ vpRelated.length }} known host{{ vpRelated.length === 1 ? \"\" : \"s\" }}</template>\n              <template v-else>An IP or a public suffix: no domain to group by.</template>\n              <span v-if=\"vpLoadedAt\"> \u00b7 updated {{ vpLoadedAt.toLocaleTimeString() }}</span>\n            </p>\n          </div>\n          <div class=\"chips\" v-if=\"vpHeadPills.length\">\n            <span v-for=\"p in vpHeadPills\" :key=\"p.text\" class=\"pill\" :class=\"p.tone\">{{ p.text }}</span>\n          </div>\n        </div>\n        <div class=\"chip-row\" v-if=\"vpRelated.length > 1\" role=\"group\" aria-label=\"Hosts of this domain\">\n          <button v-for=\"h in vpRelated\" :key=\"h\" type=\"button\" class=\"chip\" :class=\"{ on: h === activeHost }\" :aria-pressed=\"h === activeHost ? 'true' : 'false'\" @click=\"vpOpenHost(h)\">{{ h }}</button>\n          <span class=\"muted\" v-if=\"vpProfile && vpProfile.related_truncated\">(first {{ vpRelated.length }})</span>\n        </div>\n        <p class=\"muted\" v-if=\"vpLoading && !vpProfile\">Loading what applies to {{ activeHost }}\u2026</p>\n        <p class=\"danger-text\" v-if=\"vpProfileError\">{{ vpProfileError }}</p>\n        <div class=\"vp-posture\" v-if=\"vpTiles.length\">\n          <div v-for=\"t in vpTiles\" :key=\"t.key\" class=\"vp-tile\" :class=\"{ inherit: t.inherited }\">\n            <div class=\"vp-k\">{{ t.title }}</div>\n            <div class=\"vp-v\"><span v-for=\"p in t.pills\" :key=\"p.text\" class=\"pill\" :class=\"p.tone\">{{ p.text }}</span></div>\n            <div class=\"vp-why\">{{ t.why }}</div>\n            <a class=\"vp-edit\" :href=\"t.edit.href\">{{ t.edit.label }} \u2192</a>\n          </div>\n        </div>\n        <p class=\"muted vp-note\" v-if=\"vpTiles.length\">A dashed tile is decided by a broader entry (the apex, a <code>*.domain</code> entry or the node default), not by one written for this host.</p>\n      </section>\n\n      <nav class=\"vp-tabs card wide\" role=\"tablist\" aria-label=\"Vhost views\">\n        <button v-for=\"t in vpTabs\" :key=\"t.key\" type=\"button\" role=\"tab\" class=\"vp-tab\" :class=\"{ on: vpTab === t.key }\" :aria-selected=\"vpTab === t.key ? 'true' : 'false'\" @click=\"vpSetTab(t.key)\">{{ t.label }}</button>\n      </nav>\n\n      <!-- Overview -->\n      <template v-if=\"vpTab === 'overview'\">\n        <section class=\"card\">\n          <h2>Who is visiting, and what it costs the origin</h2>\n          <p class=\"muted\">The Web Traffic labels for this host, last {{ vpWindow }}. Labels never act by themselves.</p>\n          <p class=\"danger-text\" v-if=\"vpMixError\">{{ vpMixError }}</p>\n          <div class=\"vp-tiles\">\n            <div class=\"summary-card\"><h4>Requests</h4><div class=\"vp-big\">{{ vpCount(vpTraffic.requests) }}</div><div class=\"muted\">{{ vpRate(vpTraffic.rpsAvg) }} average</div></div>\n            <div class=\"summary-card\"><h4>Origin time</h4><div class=\"vp-big\">{{ vpSeconds(vpTraffic.originSec) }}</div><div class=\"muted\">PHP / upstream</div></div>\n            <div class=\"summary-card\"><h4>Bot share \u00b7 requests</h4><div class=\"vp-big\">{{ vpPct(vpTraffic.botRequestShare) }}</div><div class=\"muted\">automation + crawlers + bots</div></div>\n            <div class=\"summary-card\"><h4>Bot share \u00b7 origin</h4><div class=\"vp-big\">{{ vpPct(vpTraffic.botOriginShare) }}</div><div class=\"muted\">of the origin time</div></div>\n          </div>\n          <div class=\"vp-bar-row\"><span class=\"muted\">Requests</span><div class=\"vp-bar\"><span v-for=\"s in vpBars.requests\" :key=\"s.key\" :style=\"{ flexBasis: (s.frac * 100) + '%', background: vpColor(s.key) }\" :title=\"vpClassLabel(s.key) + ': ' + vpPct(s.frac)\"></span></div></div>\n          <div class=\"vp-bar-row\"><span class=\"muted\">Origin time</span><div class=\"vp-bar\"><span v-for=\"s in vpBars.origin\" :key=\"s.key\" :style=\"{ flexBasis: (s.frac * 100) + '%', background: vpColor(s.key) }\" :title=\"vpClassLabel(s.key) + ': ' + vpPct(s.frac)\"></span></div></div>\n          <div class=\"vp-legend\"><span v-for=\"k in ['automation','crawler','bot','human']\" :key=\"k\"><i :style=\"{ background: vpColor(k) }\"></i>{{ vpClassLabel(k) }}</span></div>\n        </section>\n        <section class=\"card\">\n          <h2>Security, last {{ vpSecurity.hours }} h</h2>\n          <p class=\"muted\">WAF hits and challenge outcomes on this host.</p>\n          <div class=\"vp-tiles\">\n            <div class=\"summary-card\"><h4>WAF hits</h4><div class=\"vp-big\">{{ vpCount(vpSecurity.wafHits) }}</div><div class=\"muted\">{{ vpSecurity.topRule ? \"top: \" + vpSecurity.topRule : \"none\" }}</div></div>\n            <div class=\"summary-card\"><h4>Challenges issued</h4><div class=\"vp-big\">{{ vpCount(vpSecurity.issued) }}</div><div class=\"muted\">{{ vpSecurity.issued ? vpPct(vpSecurity.solveRate) + \" solved\" : \"none\" }}</div></div>\n          </div>\n          <div class=\"table-wrap\" v-if=\"vpWafRows.length\">\n            <table class=\"compact-table\"><thead><tr><th>Top rules</th><th class=\"vp-r\">Hits</th><th></th></tr></thead>\n              <tbody><tr v-for=\"r in vpWafRows.slice(0, 5)\" :key=\"r.rule\"><td class=\"mono\">{{ r.rule }}</td><td class=\"vp-r\">{{ vpCount(r.count) }}</td><td class=\"vp-minibar-cell\"><div class=\"vp-minibar\" :style=\"{ width: (r.width * 100) + '%' }\"></div></td></tr></tbody>\n            </table>\n          </div>\n          <p class=\"muted\" v-else>No WAF hit recorded on this host.</p>\n        </section>\n        <section class=\"card wide\">\n          <h2>Biggest bot clients on this host</h2>\n          <p class=\"muted\">By origin time. To throttle, deny or challenge one, use <a :href=\"vpEditURL('traffic')\">Web Traffic</a> (its guardrails decide what each client may be offered).</p>\n          <div class=\"table-wrap\" v-if=\"vpBots.length\">\n            <table class=\"compact-table\"><thead><tr><th>Class</th><th>Client</th><th class=\"vp-r\">Requests</th><th class=\"vp-r\">Origin time</th><th>Share of origin</th><th class=\"vp-r\">IPs (1 h)</th></tr></thead>\n              <tbody><tr v-for=\"c in vpBots\" :key=\"c.class + c.client\">\n                <td><span class=\"vp-cls\"><i :style=\"{ background: vpColor(c.class) }\"></i>{{ vpClassLabel(c.class) }}</span></td>\n                <td class=\"mono vp-client\">{{ c.client }}</td>\n                <td class=\"vp-r\">{{ vpCount(c.requests) }}</td>\n                <td class=\"vp-r\">{{ vpSeconds(c.origin_sec) }}</td>\n                <td class=\"vp-minibar-cell\"><div class=\"vp-minibar\" :style=\"{ width: (c.originShare * 100) + '%', background: vpColor(c.class) }\"></div><span class=\"muted\">{{ vpPct(c.originShare) }}</span></td>\n                <td class=\"vp-r\">{{ c.ips_last_hour ? vpCount(c.ips_last_hour) : \"\u2013\" }}</td>\n              </tr></tbody>\n            </table>\n          </div>\n          <p class=\"muted\" v-else-if=\"vpMix\">No bot client on this host in this window.</p>\n          <p class=\"muted\" v-if=\"vpDistributed.length\">{{ vpDistributed.length }} browser-UA population{{ vpDistributed.length === 1 ? \"\" : \"s\" }} labelled <strong>distributed</strong> (many addresses, few requests each, almost no static/XHR): see Bots &amp; traffic.</p>\n        </section>\n      </template>\n\n      <!-- Bots & traffic -->\n      <template v-if=\"vpTab === 'traffic'\">\n        <section class=\"card wide\">\n          <div class=\"vp-dom\">\n            <h2>Requests over time, by class</h2>\n            <label class=\"muted\">Window\n              <select class=\"input input-small\" v-model=\"vpWindow\">\n                <option value=\"15m\">15 min</option><option value=\"1h\">1 hour</option><option value=\"6h\">6 hours</option><option value=\"24h\">24 hours</option>\n              </select>\n            </label>\n          </div>\n          <p class=\"danger-text\" v-if=\"vpMixError\">{{ vpMixError }}</p>\n          <div ref=\"vpSeries\" class=\"vp-series\">\n            <svg v-if=\"vpArea.polygons.length\" :viewBox=\"'0 0 ' + vpChartW + ' ' + vpChartH\" :width=\"vpChartW\" :height=\"vpChartH\" role=\"img\" aria-label=\"Stacked area of requests by class\">\n              <g v-for=\"t in vpArea.ticks\" :key=\"'t' + t.value\">\n                <line class=\"vp-grid\" x1=\"34\" :x2=\"vpChartW - 6\" :y1=\"t.y\" :y2=\"t.y\"></line>\n                <text x=\"2\" :y=\"t.y + 3\">{{ vpTickLabel(t.value) }}</text>\n              </g>\n              <polygon v-for=\"p in vpArea.polygons\" :key=\"p.key\" :points=\"p.points\" :fill=\"vpColor(p.key)\" fill-opacity=\".82\"></polygon>\n            </svg>\n            <p class=\"muted\" v-else>Not enough data in this window yet.</p>\n          </div>\n          <div class=\"vp-legend\"><span v-for=\"k in ['automation','crawler','bot','human']\" :key=\"k\"><i :style=\"{ background: vpColor(k) }\"></i>{{ vpClassLabel(k) }}</span></div>\n        </section>\n        <section class=\"card\">\n          <h2>Per class</h2>\n          <p class=\"muted\">Status codes are not kept per vhost, so this table has no 4xx/5xx columns.</p>\n          <div class=\"table-wrap\">\n            <table class=\"compact-table\"><thead><tr><th>Class</th><th class=\"vp-r\">Requests</th><th class=\"vp-r\">Origin</th><th class=\"vp-r\">Traffic</th><th class=\"vp-r\">Peak</th></tr></thead>\n              <tbody><tr v-for=\"r in vpClassRows\" :key=\"r.key\">\n                <td><span class=\"vp-cls\"><i :style=\"{ background: vpColor(r.key) }\"></i>{{ vpClassLabel(r.key) }}</span></td>\n                <td class=\"vp-r\">{{ vpCount(r.requests) }}</td><td class=\"vp-r\">{{ vpSeconds(r.origin_sec) }}</td><td class=\"vp-r\">{{ vpBytes(r.bytes) }}</td><td class=\"vp-r\">{{ vpRate(r.rps_peak) }}</td>\n              </tr></tbody>\n            </table>\n          </div>\n        </section>\n        <section class=\"card\">\n          <h2>All clients</h2>\n          <p class=\"muted\">By origin time. A browser UA is never acted on by its UA: every real Chrome sends the same string.</p>\n          <div class=\"table-wrap stable-table-wrap\">\n            <table class=\"compact-table\"><thead><tr><th>Class</th><th>Client</th><th class=\"vp-r\">Req</th><th class=\"vp-r\">Origin</th></tr></thead>\n              <tbody><tr v-for=\"c in vpAllClients\" :key=\"c.class + c.client\">\n                <td><span class=\"vp-cls\"><i :style=\"{ background: vpColor(c.class) }\"></i>{{ vpClassLabel(c.class) }}</span><span v-if=\"c.distributed\" class=\"pill warn\" :title=\"c.distributed.ips + ' IPs, ' + c.distributed.req_per_ip + ' req/IP'\">distributed</span></td>\n                <td class=\"mono vp-client\">{{ c.client === \"_other\" ? \"(everything else)\" : c.client }}</td>\n                <td class=\"vp-r\">{{ vpCount(c.requests) }}</td><td class=\"vp-r\">{{ vpSeconds(c.origin_sec) }}</td>\n              </tr></tbody>\n            </table>\n          </div>\n        </section>\n      </template>\n\n      <!-- WAF & challenges -->\n      <template v-if=\"vpTab === 'security'\">\n        <section class=\"card\">\n          <h2>WAF hits by rule, last {{ vpSecurity.hours }} h</h2>\n          <div class=\"table-wrap\" v-if=\"vpWafRows.length\">\n            <table class=\"compact-table\"><thead><tr><th>Rule</th><th class=\"vp-r\">Hits</th><th></th></tr></thead>\n              <tbody><tr v-for=\"r in vpWafRows\" :key=\"r.rule\"><td class=\"mono\">{{ r.rule }}</td><td class=\"vp-r\">{{ vpCount(r.count) }}</td><td class=\"vp-minibar-cell\"><div class=\"vp-minibar\" :style=\"{ width: (r.width * 100) + '%' }\"></div></td></tr></tbody>\n            </table>\n          </div>\n          <p class=\"muted\" v-else>No WAF hit recorded on this host.</p>\n          <p class=\"muted\">Every hit with its request: <a :href=\"vpEditURL('waf')\">WAF engine</a>.</p>\n        </section>\n        <section class=\"card\">\n          <h2>Challenges, last {{ vpSecurity.hours }} h</h2>\n          <div class=\"vp-tiles\">\n            <div class=\"summary-card\"><h4>Issued</h4><div class=\"vp-big\">{{ vpCount(vpSecurity.issued) }}</div></div>\n            <div class=\"summary-card\"><h4>Solved</h4><div class=\"vp-big\">{{ vpCount(vpSecurity.solved) }}</div><div class=\"muted\" v-if=\"vpSecurity.issued\">{{ vpPct(vpSecurity.solveRate) }}</div></div>\n          </div>\n          <p class=\"muted\">Per-IP outcomes and the v2 rejects are on <a :href=\"'/cfm-admin/webdetector/forensics/?host=' + encodeURIComponent(activeHost)\">Forensics</a>.</p>\n        </section>\n      </template>\n\n      <!-- What applies -->\n      <template v-if=\"vpTab === 'config'\">\n        <section class=\"card wide\">\n          <h2>Traffic rules that match this host</h2>\n          <p class=\"muted\">In evaluation order, with the host test the edge uses. A disabled rule would match if enabled. An allow only ends rule evaluation: it never bypasses the WAF, a challenge or an IP block.</p>\n          <div class=\"table-wrap\" v-if=\"vpRuleRows.length\">\n            <table class=\"compact-table\"><thead><tr><th>Priority</th><th>Matches</th><th>Scope</th><th>Action</th><th>State</th><th></th></tr></thead>\n              <tbody><tr v-for=\"r in vpRuleRows\" :key=\"r.id\" :class=\"{ 'vp-dim': r.state !== 'enabled' }\">\n                <td class=\"vp-r\">{{ r.priority }}</td>\n                <td>{{ r.match }}<div class=\"muted\" v-if=\"r.note\">{{ r.note }}</div></td>\n                <td class=\"mono\">{{ r.matchedBy }}<span v-if=\"r.inherited\" class=\"pill\">wider</span></td>\n                <td><span class=\"pill\" :class=\"r.actionTone\">{{ r.action }}</span></td>\n                <td><span class=\"pill\" :class=\"r.stateTone\">{{ r.state }}</span><div class=\"muted\" v-if=\"r.until\">until {{ r.until }}</div></td>\n                <td><a :href=\"vpEditURL('rules')\">Open \u2192</a></td>\n              </tr></tbody>\n            </table>\n          </div>\n          <p class=\"muted\" v-else-if=\"vpProfile\">No traffic rule's scope takes this host.</p>\n        </section>\n        <section class=\"card wide\">\n          <h2>Excludes in effect</h2>\n          <p class=\"muted\">\"Outside its scope\" marks a WAF exclude the edge applies here although its scope names other hosts: the in-path WAF does not read an exclude's scope yet.</p>\n          <div class=\"table-wrap\" v-if=\"vpExcludeRows.length\">\n            <table class=\"compact-table\"><thead><tr><th>Kind</th><th>Entry</th><th>Skips</th><th>Scope</th></tr></thead>\n              <tbody><tr v-for=\"(x, i) in vpExcludeRows\" :key=\"i\">\n                <td>{{ x.kind }}</td>\n                <td><span class=\"muted\">{{ x.type }}</span> <span class=\"mono\">{{ x.value }}</span><span v-if=\"x.exact\" class=\"pill info\">this host</span></td>\n                <td>{{ x.rules }}</td>\n                <td>{{ x.scope }}<span v-if=\"x.outsideScope\" class=\"pill warn\">outside its scope</span></td>\n              </tr></tbody>\n            </table>\n          </div>\n          <p class=\"muted\" v-else-if=\"vpProfile\">No WAF or challenge exclude applies to this host.</p>\n        </section>\n      </template>\n    </template>",
  webtop: "<section class=\"card card-tall\" v-if=\"shouldShow('webtop')\">\n        <h2>WebTop (short window)</h2>\n        <p class=\"muted\">Data source: <code>/api/v1/webdet/top-short</code> proxied via <code>/cfm-admin/api/</code>.</p>\n        <div class=\"toolbar\">\n          <label for=\"top-short-limit\">Top</label>\n          <input\n            id=\"top-short-limit\"\n            class=\"input\"\n            type=\"number\"\n            min=\"1\"\n            max=\"500\"\n            step=\"1\"\n            v-model.number=\"topShortLimit\"\n            @change=\"refreshAll\"\n          />\n          <span class=\"muted\">vhosts (default 20)</span>\n        </div>\n        " + SIGNAL_LEGEND + "\n        <div class=\"table-wrap stable-table-wrap\">\n          <table>\n            <thead>\n              <tr>\n                <th>Host</th>\n                <th>RPS</th>\n                <th>2xx</th>\n                <th>4xx</th>\n                <th>5xx</th>\n                <th>Unique IPs</th>\n                <th>Score</th>\n                <th>Flags</th>\n                <th>Actions</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr v-for=\"row in topShort\" :key=\"row.host\" @click=\"loadHost(row.host)\" class=\"clickable\">\n                <td>{{ row.host || '-' }}</td>\n                <td>{{ num(row.rps) }}</td>\n                <td>{{ num(row.rps_2xx) }}</td>\n                <td>{{ num(row.rps_4xx) }}</td>\n                <td>{{ num(row.rps_5xx) }}</td>\n                <td>{{ num(row.unique_ips) }}</td>\n                <td>{{ num(row.score) }}</td>\n                <td>\n                  <span class=\"pill warn\" v-if=\"suspiciousHosts[row.host]\">suspicious</span>\n                  <span class=\"pill danger\" v-if=\"challengeState(row.host)\">challenged</span>\n                  <span class=\"pill attack\" v-if=\"underAttackState(row.host)\" title=\"Under-Attack Mode: this vhost was challenge-armed and the challenge is being defeated (or an operator forced it).\">🚨 under attack</span>\n                  <span class=\"pill info\" v-if=\"row.solver_farm\" title=\"challenge_solver_farm sees a distributed solver farm on this vhost right now: many one-solve-per-address clients, spread across distinct subnets. Alert-only.\">farm</span>\n                  <span class=\"pill warn\" v-if=\"row.shadow_outliers > 0\" :title=\"'abuse_shadow sees ' + row.shadow_outliers + ' rate-outlier IP(s) on this vhost right now (rate vs the vhost median; shadow/log-only, see cfm.abuse_shadow.log). May include verified crawlers.'\">shadow {{ row.shadow_outliers }}</span>\n                  <span class=\"pill warn\" v-if=\"row.query_cardinality > 0\" :title=\"'abuse_shadow facet: ' + row.query_cardinality + ' distinct query URLs on very few base paths right now (query-cardinality expansion that path_diversity cannot see; shadow/log-only, see cfm.abuse_shadow.log).'\">facet {{ row.query_cardinality }}</span>\n                  <span class=\"pill danger\" v-if=\"row.cost_pressure > 0\" :title=\"'abuse_shadow cost: origin is returning ' + row.cost_pressure + '% 5xx on this vhost right now (cost pressure / origin collapse; shadow/log-only, see cfm.abuse_shadow.log).'\">cost {{ row.cost_pressure }}%</span>\n                  <span class=\"pill info\" v-if=\"row.dc_fraction > 0\" :title=\"row.dc_fraction + '% of this vhost traffic is from unverified datacenter/cloud ASNs right now (verified crawlers excluded via FCrDNS). Corroborating feature only, never a decision on its own; shadow/log-only, see cfm.abuse_shadow.log.'\">dc {{ row.dc_fraction }}%</span>\n                </td>\n                <td class=\"actions-cell\">\n                  <button class=\"btn-quiet\" @click.stop=\"toggleChallenge(row.host)\">{{ challengeState(row.host) ? 'Unchallenge' : 'Challenge' }}</button>\n                  <button class=\"btn-quiet\" @click.stop=\"openVhostLive(row.host)\">Live</button>\n                  <button class=\"btn-quiet\" @click.stop=\"openForensics(row.host)\">Forensics</button>\n                  <button class=\"btn-quiet\" @click.stop=\"historyForHost(row.host)\">History</button>\n                </td>\n              </tr>\n              <tr v-if=\"!topShort.length\"><td colspan=\"9\" class=\"muted\">No data yet.</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <details class=\"raw-json\" v-if=\"hotIPs.length\">\n          <summary>\u25ba Hot IPs endpoint rows ({{ hotIPs.length }})</summary>\n          <div class=\"table-wrap\">\n            <table class=\"mini-table compact-table\">\n              <thead><tr><th>IP</th><th>Req</th><th>RPS</th><th>Score</th><th>CC</th><th>ASN</th></tr></thead>\n              <tbody>\n                <tr v-for=\"r in hotIPs\" :key=\"r.ip\">\n                  <td><code>{{ r.ip }}</code></td>\n                  <td>{{ r.req }}</td>\n                  <td>{{ num(r.rps) }}</td>\n                  <td>{{ num(r.score) }}</td>\n                  <td>{{ r.country || '-' }}</td>\n                  <td class=\"truncate\" :title=\"r.asn_name\">{{ r.asn ? `AS${String(r.asn).replace(/^AS/i,'')}` : '-' }}</td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n        </details>\n      </section>",
  globalips: "<section class=\"card card-tall\" v-if=\"shouldShow('globalips')\">\n        <h2>Global Top IPs</h2>\n        <div class=\"toolbar\">\n          <label for=\"ip-short-limit\">Top</label>\n          <input\n            id=\"ip-short-limit\"\n            class=\"input\"\n            type=\"number\"\n            min=\"1\"\n            max=\"500\"\n            step=\"1\"\n            v-model.number=\"ipShortLimit\"\n            @change=\"refreshAll\"\n          />\n          <span class=\"muted\">IPs</span>\n          <label for=\"block-ttl\">Block TTL</label>\n          <select id=\"block-ttl\" class=\"input\" v-model=\"blockTTL\" title=\"TTL used by the Block buttons on this page ('permanent' asks for confirmation)\">\n            <option v-for=\"c in blockTTLChoices\" :key=\"c.label\" :value=\"c.value\">{{ c.label }}</option>\n          </select>\n        </div>\n        <div class=\"table-wrap stable-table-wrap\">\n          <table>\n            <thead>\n              <tr><th class=\"checkbox-cell\"><input type=\"checkbox\" :checked=\"allRowsSelected(ipShort, 'ip')\" @change=\"toggleSelectAllRows(ipShort, 'ip')\" title=\"Select/unselect all listed IPs\" /></th><th>IP</th><th>Req</th><th>Vhosts</th><th>RPS</th><th>Score</th><th>CC</th><th>ASN</th><th>Actions</th></tr>\n            </thead>\n            <tbody>\n              <tr v-for=\"row in ipShort\" :key=\"row.ip\" class=\"clickable\" :class=\"{ 'bulk-selected': isIPSelected(row.ip) }\" @click=\"loadIP(row.ip)\">\n                <td class=\"checkbox-cell\" @click.stop>\n                  <input type=\"checkbox\" :checked=\"isIPSelected(row.ip)\" @change=\"toggleIPSelected(row.ip)\" />\n                </td>\n                <td><code>{{ row.ip }}</code></td>\n                <td>{{ row.req }}</td>\n                <td>{{ row.vhosts }}</td>\n                <td>{{ num(row.rps) }}</td>\n                <td>{{ num(row.score) }}</td>\n                <td><span class=\"quick-select\" v-if=\"row.country\" @click.stop=\"selectRowsMatching(ipShort, 'ip', 'country', row.country)\" :title=\"'Select all listed IPs from ' + row.country\">{{ row.country }}</span><span v-else>-</span></td>\n                <td class=\"truncate\" :title=\"row.asn_name || row.asn\"><span class=\"quick-select\" v-if=\"row.asn\" @click.stop=\"selectRowsMatching(ipShort, 'ip', 'asn', row.asn)\" :title=\"'Select all listed IPs of AS' + String(row.asn).replace(/^AS/i, '') + (row.asn_name ? ' \u2014 ' + row.asn_name : '')\">AS{{ String(row.asn).replace(/^AS/i, '') }} {{ row.asn_name || '' }}</span><span v-else>-</span></td>\n                <td class=\"actions-cell\">\n                  <button class=\"btn-quiet\" @click.stop=\"challengeIPTopHost(row.ip)\" :title=\"'Manual-challenge the top host of this IP for ' + challengeTTLLabel\">Challenge</button>\n                  <button class=\"btn-danger\" @click.stop=\"blockIP(row.ip)\">Block {{ blockTTLLabel }}</button>\n                  <button class=\"btn-quiet\" @click.stop=\"analyzeIP(row.ip)\">Analyze</button>\n                  <button class=\"btn-quiet\" @click.stop=\"historyForIP(row.ip)\">History</button>\n                </td>\n              </tr>\n              <tr v-if=\"!ipShort.length\"><td colspan=\"9\" class=\"muted\">No IP rows.</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"bulkbar\" v-if=\"selectedIPCount\">\n          <strong>{{ selectedIPCount }} IP(s) selected</strong>\n          <button class=\"btn-danger\" :disabled=\"bulkBusy\" @click=\"bulkBlockSelected\">Block selected ({{ blockTTLLabel }})</button>\n          <button class=\"btn-quiet\" :disabled=\"bulkBusy\" @click=\"clearIPSelection\">Clear selection</button>\n          <span class=\"muted\" v-if=\"bulkProgress\">{{ bulkProgress }}</span>\n        </div>\n      </section>",
  suspicious: "<section class=\"card wide\" v-if=\"shouldShow('suspicious')\">\n        <h2>Suspicious + challenged vhosts</h2>\n        <div class=\"toolbar\">\n          <label for=\"challenge-ttl\">Challenge TTL</label>\n          <select id=\"challenge-ttl\" class=\"input\" v-model=\"challengeTTL\" title=\"TTL used by the Challenge / Manual challenge buttons on this page\">\n            <option v-for=\"c in challengeTTLChoices\" :key=\"c.value\" :value=\"c.value\">{{ c.label }}</option>\n          </select>\n          <label for=\"challenge-rung\">Tier</label>\n          <select id=\"challenge-rung\" class=\"input\" v-model=\"challengeRung\" title=\"challenge = plain PoW; challenge v2 = a solve must ALSO pass the passive humanity check (headless farms earn no clearance)\">\n            <option v-for=\"c in challengeRungChoices\" :key=\"c.value\" :value=\"c.value\">{{ c.label }}</option>\n          </select>\n        </div>\n        " + SIGNAL_LEGEND + "\n        <div class=\"table-wrap stable-table-wrap wide-table-wrap\">\n          <table>\n            <thead>\n              <tr>\n                <th>Host</th>\n                <th>Score</th>\n                <th>Reasons</th>\n                <th>RPS</th>\n                <th>uniqIP</th>\n                <th>err%</th>\n                <th>bot%</th>\n                <th>ua_div</th>\n                <th>path_div</th>\n                <th>Status</th>\n                <th>Actions</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr v-for=\"row in suspiciousAndChallenged\" :key=\"row.host\" class=\"clickable\" @click=\"loadHost(row.host)\">\n                <td>{{ row.host || '-' }}</td>\n                <td>{{ num(row.score) }}</td>\n                <td class=\"truncate\" :title=\"reasonText(row)\">{{ reasonText(row) }}</td>\n                <td>{{ num(row.rps) }}</td>\n                <td>{{ num(row.unique_ips) }}</td>\n                <td>{{ pct(row.err_ratio) }}</td>\n                <td>{{ pct(row.bot_ratio) }}</td>\n                <td>{{ num(row.ua_diversity) }}</td>\n                <td>{{ num(row.path_diversity) }}</td>\n                <td style=\"white-space: nowrap;\">\n                  <span class=\"pill warn\" v-if=\"row.fromSuspicious\">suspicious</span>\n                  <span class=\"pill danger\" v-if=\"challengeState(row.host)\">challenged</span>\n                  <span class=\"pill attack\" v-if=\"underAttackState(row.host)\" title=\"Under-Attack Mode: this vhost was challenge-armed and the challenge is being defeated (or an operator forced it).\">🚨 under attack</span>\n                  <span class=\"pill info\" v-if=\"row.solver_farm\" title=\"challenge_solver_farm sees a distributed solver farm on this vhost right now: many one-solve-per-address clients, spread across distinct subnets. Alert-only.\">farm</span>\n                  <span class=\"pill warn\" v-if=\"row.shadow_outliers > 0\" :title=\"'abuse_shadow sees ' + row.shadow_outliers + ' rate-outlier IP(s) on this vhost right now (rate vs the vhost median; shadow/log-only, see cfm.abuse_shadow.log). May include verified crawlers.'\">shadow {{ row.shadow_outliers }}</span>\n                  <span class=\"pill warn\" v-if=\"row.query_cardinality > 0\" :title=\"'abuse_shadow facet: ' + row.query_cardinality + ' distinct query URLs on very few base paths right now (query-cardinality expansion that path_diversity cannot see; shadow/log-only, see cfm.abuse_shadow.log).'\">facet {{ row.query_cardinality }}</span>\n                  <span class=\"pill danger\" v-if=\"row.cost_pressure > 0\" :title=\"'abuse_shadow cost: origin is returning ' + row.cost_pressure + '% 5xx on this vhost right now (cost pressure / origin collapse; shadow/log-only, see cfm.abuse_shadow.log).'\">cost {{ row.cost_pressure }}%</span>\n                  <span class=\"pill info\" v-if=\"row.dc_fraction > 0\" :title=\"row.dc_fraction + '% of this vhost traffic is from unverified datacenter/cloud ASNs right now (verified crawlers excluded via FCrDNS). Corroborating feature only, never a decision on its own; shadow/log-only, see cfm.abuse_shadow.log.'\">dc {{ row.dc_fraction }}%</span>\n                  <span class=\"pill\" v-if=\"challengeModeLabel(row.host)\" :title=\"challengeModeTitle(row.host)\">{{ challengeModeLabel(row.host) }}</span>\n                </td>\n                <td class=\"actions-cell\">\n                  <button class=\"btn-quiet btn-sm\" @click.stop=\"toggleChallenge(row.host, challengeRung)\">{{ challengeState(row.host) ? 'Unchallenge' : 'Challenge' }}</button>\n                  <button class=\"btn-quiet btn-sm\" @click.stop=\"manualChallenge(row.host, challengeRung)\" v-if=\"!challengeState(row.host)\" :title=\"'Enable manual challenge for ' + challengeTTLLabel + ' (persists across auto-refresh)'\">Manual</button>\n                  <button class=\"btn-quiet btn-sm\" @click.stop=\"toggleChallengeTier(row.host)\" v-if=\"challengeTierTarget(row.host)\" :title=\"challengeTierButtonTitle(row.host)\">{{ challengeTierButtonLabel(row.host) }}</button>\n                  <button class=\"btn-quiet btn-sm\" @click.stop=\"unpinChallengeTier(row.host)\" v-if=\"challengeTierPinned(row.host)\" title=\"Remove the tier pin: CHALLENGE_V2_AUTO_VHOST decides this vhost's tier again\">↺ auto</button>\n                  <button class=\"btn-quiet btn-sm\" @click.stop=\"openVhostLive(row.host)\">Live</button>\n                  <button class=\"btn-quiet btn-sm\" @click.stop=\"openForensics(row.host)\">Forensics</button>\n                  <button class=\"btn-quiet btn-sm\" @click.stop=\"historyForHost(row.host)\">History</button>\n                </td>\n              </tr>\n              <tr v-if=\"!suspiciousAndChallenged.length\"><td colspan=\"11\" class=\"muted\">No suspicious/challenged hosts.</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </section>",
  longtop: "<section class=\"card wide\" v-if=\"shouldShow('longtop')\">\n        <h2>Long window top</h2>\n        <div class=\"toolbar\">\n          <label for=\"long-top-limit\">Top</label>\n          <input\n            id=\"long-top-limit\"\n            class=\"input\"\n            type=\"number\"\n            min=\"1\"\n            max=\"500\"\n            step=\"1\"\n            v-model.number=\"longTopLimit\"\n            @change=\"refreshAll\"\n          />\n          <span class=\"muted\">hosts</span>\n        </div>\n        <div class=\"table-wrap stable-table-wrap\">\n          <table>\n            <thead>\n              <tr><th>Host</th><th>Score</th><th>Reasons</th><th>RPS</th><th>err%</th><th>bot%</th><th>Actions</th></tr>\n            </thead>\n            <tbody>\n              <tr v-for=\"row in longTop\" :key=\"row.host\" class=\"clickable\" @click=\"loadHost(row.host)\">\n                <td>{{ row.host || '-' }}</td>\n                <td>{{ num(row.score) }}</td>\n                <td class=\"truncate\" :title=\"reasonText(row)\">{{ reasonText(row) }}</td>\n                <td>{{ num(row.rps) }}</td>\n                <td>{{ pct(row.err_ratio) }}</td>\n                <td>{{ pct(row.bot_ratio) }}</td>\n                <td class=\"actions-cell\">\n                  <button class=\"btn-quiet\" @click.stop=\"toggleChallenge(row.host)\">{{ challengeState(row.host) ? 'Unchallenge' : 'Challenge' }}</button>\n                  <button class=\"btn-quiet\" @click.stop=\"openVhostLive(row.host)\">Live</button>\n                  <button class=\"btn-quiet\" @click.stop=\"openForensics(row.host)\">Forensics</button>\n                  <button class=\"btn-quiet\" @click.stop=\"historyForHost(row.host)\">History</button>\n                </td>\n              </tr>\n              <tr v-if=\"!longTop.length\"><td colspan=\"7\" class=\"muted\">No long-window rows.</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </section>",
  excludes: "<section class=\"card wide\" v-if=\"shouldShow('excludes')\">\n        <h2>Dynamic excludes (Challenge / WAF)</h2>\n        <p class=\"muted\">Manage runtime excludes that are persisted on the server and reused by CLI/API.</p>\n        <div class=\"exclude-grid\">\n          <section class=\"mini-card\">\n            <h3>Challenge excludes</h3>\n            <div class=\"toolbar\">\n              <select class=\"input\" v-model=\"challengeExcludeType\">\n                <option value=\"host\">host</option>\n                <option value=\"path\" v-if=\"pathTypeAllowedFor('challenge')\">path</option>\n              </select>\n              <input class=\"input input-wide\" type=\"text\" v-model.trim=\"challengeExcludeValue\" placeholder=\"example.com or /images/.tmb/\" />\n              <input class=\"input input-small\" v-if=\"challengeExcludeType === 'path'\" type=\"text\" v-model.trim=\"challengeExcludeScope\" :placeholder=\"isScoped ? 'your site(s), required' : 'scope host(s), required'\" title=\"Comma-separated vhosts this path exclude applies to; each also covers its www. alias. Required.\" />\n              <button class=\"btn-quiet\" @click=\"addExclude('challenge')\">Add</button>\n            </div>\n            <p class=\"muted\" v-if=\"challengeExcludeType === 'path'\">A path exclude stops the malpath challenge and the malpath ban from counting requests under this path (e.g. <code>/images/.tmb/</code>) on these sites only. Every other path, and this path on any other site, is still checked. The first path segment must be a name, not a wildcard.</p>\n            <div class=\"table-wrap\">\n              <table>\n                <thead><tr><th>Type</th><th>Value</th><th>Scope</th><th>Created</th><th>Action</th></tr></thead>\n                <tbody>\n                  <tr v-for=\"row in challengeExcludes\" :key=\"`ch-${row.type}-${row.value}-${(row.scope_hosts || []).join(',')}-${row.created_at || ''}`\">\n                    <td>{{ row.type }}</td>\n                    <td><code>{{ row.value }}</code></td>\n                    <td>{{ formatChallengeExcludeScope(row) }}</td>\n                    <td>{{ row.created_at || '-' }}</td>\n                    <td><button class=\"btn-quiet\" @click=\"removeExclude('challenge', row)\">Remove</button></td>\n                  </tr>\n                  <tr v-if=\"!challengeExcludes.length\"><td colspan=\"5\" class=\"muted\">No challenge excludes.</td></tr>\n                </tbody>\n              </table>\n            </div>\n          </section>\n\n          <section class=\"mini-card\">\n            <h3>WAF excludes</h3>\n            <div class=\"toolbar\">\n              <select class=\"input\" v-model=\"wafExcludeType\">\n                <option value=\"host\">host</option>\n                <option value=\"path\" v-if=\"pathTypeAllowedFor('waf')\">path</option>\n              </select>\n              <input class=\"input input-wide\" type=\"text\" v-model.trim=\"wafExcludeValue\" placeholder=\"example.com or /api/callback\" />\n              <input class=\"input input-small\" type=\"text\" v-model.trim=\"wafExcludeRules\" placeholder=\"rule IDs (optional)\" title=\"Comma-separated WAF rule IDs, e.g. 402 or 401,431-436. Empty = whole-WAF exclude (all rules).\" />\n              <input class=\"input input-small\" v-if=\"!isScoped\" type=\"text\" v-model.trim=\"wafExcludeScope\" placeholder=\"scope host (optional)\" title=\"Restrict this exclude to one or more vhosts (comma-separated). Empty = all vhosts. Admin only — scoped tokens are always pinned to their own vhost.\" />\n              <button class=\"btn-quiet\" @click=\"addExclude('waf')\">Add</button>\n            </div>\n            <div class=\"table-wrap\">\n              <table>\n                <thead><tr><th>Type</th><th>Value</th><th>Rules</th><th>Scope</th><th>Created</th><th>Action</th></tr></thead>\n                <tbody>\n                  <tr v-for=\"row in wafExcludes\" :key=\"`waf-${row.type}-${row.value}-${(row.rule_ids || []).join('.')}-${(row.scope_hosts || []).join('.')}`\">\n                    <td>{{ row.type }}</td>\n                    <td><code>{{ row.value }}</code></td>\n                    <td>{{ formatExcludeRules(row.rule_ids) }}</td>\n                    <td>{{ formatExcludeScope(row.scope_hosts) }}</td>\n                    <td>{{ row.created_at || '-' }}</td>\n                    <td><button class=\"btn-quiet\" @click=\"removeExclude('waf', row)\">Remove</button></td>\n                  </tr>\n                  <tr v-if=\"!wafExcludes.length\"><td colspan=\"6\" class=\"muted\">No WAF excludes.</td></tr>\n                </tbody>\n              </table>\n            </div>\n          </section>\n        </div>\n      </section>",
  drilldown: "<section class=\"card wide\" id=\"drilldown-card\" v-if=\"shouldShow('vhost')\">\n        <h2>Vhost drilldown</h2>\n        <p class=\"muted\" v-if=\"activeHost\">Drilldown for: <strong>{{ activeHost }}</strong></p>\n        <p class=\"muted\" v-else>Click any host above to inspect.</p>\n        <div class=\"toolbar\" v-if=\"activeHost\">\n          <button class=\"btn-quiet\" @click=\"openForensics(activeHost)\">Open in Forensics tab</button>\n        </div>\n        <p v-if=\"actionMsg\" class=\"statusline\">{{ actionMsg }}</p>\n\n        <div class=\"drill-grid\" v-if=\"shortDetail\">\n          <section class=\"mini-card metrics-card\">\n            <h3>Key metrics</h3>\n            <table class=\"mini-table compact-table\">\n              <tbody>\n                <tr v-for=\"m in keyMetrics\" :key=\"m.label\">\n                  <td>{{ m.label }}</td>\n                  <td>{{ m.value }}</td>\n                </tr>\n              </tbody>\n            </table>\n            <div class=\"long-score\" v-if=\"longDetail\">\n              <div>Long score: <strong>{{ num(longDetail.score) }}</strong></div>\n              <div class=\"muted\" v-if=\"longReasons.length\">{{ longReasons.join(', ') }}</div>\n            </div>\n          </section>\n\n          <section class=\"mini-card ips-card\" v-if=\"topIPRows.length\">\n            <h3>Top IPs ({{ vhostTopIPLimit }})</h3>\n            <div class=\"toolbar\">\n              <label>Show</label>\n              <select class=\"input\" v-model.number=\"vhostTopIPLimit\" title=\"How many top IPs to list\">\n                <option :value=\"25\">25</option>\n                <option :value=\"50\">50</option>\n                <option :value=\"100\">100</option>\n              </select>\n              <label>Block TTL</label>\n              <select class=\"input\" v-model=\"blockTTL\" title=\"TTL used by the Block buttons ('permanent' asks for confirmation)\">\n                <option v-for=\"c in blockTTLChoices\" :key=\"c.label\" :value=\"c.value\">{{ c.label }}</option>\n              </select>\n            </div>\n            <table class=\"mini-table\">\n              <thead><tr><th class=\"checkbox-cell\"><input type=\"checkbox\" :checked=\"allRowsSelected(visibleTopIPRows, 'key')\" @change=\"toggleSelectAllRows(visibleTopIPRows, 'key')\" title=\"Select/unselect all listed IPs\" /></th><th>IP</th><th>Count</th><th>CC</th><th>ASN</th><th>Company</th><th>Action</th></tr></thead>\n              <tbody>\n                <tr v-for=\"ipRow in visibleTopIPRows\" :key=\"ipRow.key\" :class=\"{ 'bulk-selected': isIPSelected(ipRow.key) }\">\n                  <td class=\"checkbox-cell\"><input type=\"checkbox\" :checked=\"isIPSelected(ipRow.key)\" @change=\"toggleIPSelected(ipRow.key)\" /></td>\n                  <td><code>{{ ipRow.key }}</code></td>\n                  <td>{{ ipRow.count }}</td>\n                  <td><span class=\"quick-select\" v-if=\"ipRow.country && ipRow.country !== '-'\" @click=\"selectRowsMatching(visibleTopIPRows, 'key', 'country', ipRow.country)\" :title=\"'Select all listed IPs from ' + ipRow.country\">{{ ipRow.country }}</span><span v-else>{{ ipRow.country }}</span></td>\n                  <td><span class=\"quick-select\" v-if=\"ipRow.asn && ipRow.asn !== '-'\" @click=\"selectRowsMatching(visibleTopIPRows, 'key', 'asn', ipRow.asn)\" :title=\"'Select all listed IPs of ' + ipRow.asn\">{{ ipRow.asn }}</span><span v-else>{{ ipRow.asn }}</span></td>\n                  <td class=\"truncate\" :title=\"ipRow.company\"><span class=\"quick-select\" v-if=\"ipRow.company && ipRow.company !== '-'\" @click=\"selectRowsMatching(visibleTopIPRows, 'key', 'company', ipRow.company)\">{{ ipRow.company }}</span><span v-else>{{ ipRow.company }}</span></td>\n                  <td>\n                    <button class=\"btn-danger\" @click=\"blockIP(ipRow.key)\">Block {{ blockTTLLabel }}</button>\n                    <button class=\"btn-quiet\" @click=\"historyForIP(ipRow.key)\">History</button>\n                  </td>\n                </tr>\n              </tbody>\n            </table>\n            <div class=\"bulkbar\" v-if=\"selectedIPCount\">\n              <strong>{{ selectedIPCount }} IP(s) selected</strong>\n              <button class=\"btn-danger\" :disabled=\"bulkBusy\" @click=\"bulkBlockSelected\">Block selected ({{ blockTTLLabel }})</button>\n              <button class=\"btn-quiet\" :disabled=\"bulkBusy\" @click=\"clearIPSelection\">Clear selection</button>\n              <span class=\"muted\" v-if=\"bulkProgress\">{{ bulkProgress }}</span>\n            </div>\n          </section>\n\n          <section class=\"mini-card path-card\" v-if=\"topPaths.length\">\n            <h3>Top paths</h3>\n            <table class=\"mini-table\">\n              <thead><tr><th>Path</th><th>Count</th></tr></thead>\n              <tbody>\n                <tr v-for=\"p in topPaths.slice(0, 8)\" :key=\"p.key\"><td><code>{{ p.key }}</code></td><td>{{ p.count }}</td></tr>\n              </tbody>\n            </table>\n          </section>\n\n          <section class=\"mini-card agent-card\" v-if=\"topAgents.length\">\n            <h3>Top user-agents</h3>\n            <table class=\"mini-table compact-table\">\n              <thead><tr><th>User-Agent</th><th>Count</th></tr></thead>\n              <tbody>\n                <tr v-for=\"a in topAgents.slice(0, 6)\" :key=\"a.key\"><td>{{ a.key }}</td><td>{{ a.count }}</td></tr>\n              </tbody>\n            </table>\n          </section>\n        </div>\n\n        <details class=\"raw-json\" v-if=\"shortDetail\">\n          <summary>Raw JSON (for debugging)</summary>\n          <pre>{{ rawDrilldownPretty }}</pre>\n        </details>\n        <pre v-else>Select a host to load drilldown details.</pre>\n      </section>",
  drilldownlive: "<section class=\"card wide\" id=\"drilldown-card\" v-if=\"shouldShow('vhost')\">\n        <h2>Vhost drilldown</h2>\n        <p class=\"muted\" v-if=\"activeHost\">Drilldown for: <strong>{{ activeHost }}</strong></p>\n        <p class=\"muted\" v-else>Click any host above to inspect.</p>\n        <p v-if=\"actionMsg\" class=\"statusline\">{{ actionMsg }}</p>\n\n        <section class=\"mini-card live-headline\" v-if=\"shortDetail\">\n          <div class=\"headline-row\">\n            <span class=\"pill danger\" v-if=\"challengeState(activeHost)\">CHALLENGE {{ liveKPI.challengeMode || 'manual' }}</span>\n            <span>score:<strong>{{ num(liveKPI.score) }}</strong></span>\n            <span>err:<strong>{{ num(liveKPI.errPct) }}%</strong></span>\n            <span>rt:<strong>{{ num(liveKPI.rtMs) }}ms</strong></span>\n            <span>uniqIP:<strong>{{ num(liveKPI.uniqIP) }}</strong></span>\n            <span>bot:<strong>{{ num(liveKPI.botPct) }}%</strong></span>\n            <span class=\"muted\" v-if=\"liveKPI.reasons.length\">reasons:{{ liveKPI.reasons.join(', ') }}</span>\n          </div>\n        </section>\n\n        <div class=\"live-chart-grid\" v-if=\"activeVhostSeries.length > 1\">\n          <section class=\"mini-card\">\n            <h3>Traffic RPS (2xx / 4xx / 5xx)</h3>\n            <div id=\"vhost-rps-chart\" class=\"spark echart-box\"></div>\n          </section>\n          <section class=\"mini-card\">\n            <h3>Bot %</h3>\n            <div id=\"vhost-bot-chart\" class=\"spark echart-box\"></div>\n          </section>\n          <section class=\"mini-card\">\n            <h3>Error rate %</h3>\n            <div id=\"vhost-err-chart\" class=\"spark echart-box\"></div>\n          </section>\n          <section class=\"mini-card\">\n            <h3>Threat score</h3>\n            <div id=\"vhost-score-chart\" class=\"spark echart-box\"></div>\n          </section>\n          <section class=\"mini-card\">\n            <h3>Response time (ms)</h3>\n            <div id=\"vhost-rt-chart\" class=\"spark echart-box\"></div>\n          </section>\n        </div>\n\n        <div class=\"drill-grid\" v-if=\"shortDetail\">\n          <section class=\"mini-card metrics-card\">\n            <h3>Key metrics</h3>\n            <table class=\"mini-table compact-table\">\n              <tbody>\n                <tr v-for=\"m in keyMetrics\" :key=\"m.label\">\n                  <td>{{ m.label }}</td>\n                  <td>{{ m.value }}</td>\n                </tr>\n              </tbody>\n            </table>\n            <div class=\"long-score\" v-if=\"longDetail\">\n              <div>Long score: <strong>{{ num(longDetail.score) }}</strong></div>\n              <div class=\"muted\" v-if=\"longReasons.length\">{{ longReasons.join(', ') }}</div>\n            </div>\n          </section>\n\n          <section class=\"mini-card ips-card\" v-if=\"topIPRows.length\">\n            <h3>Top IPs ({{ vhostTopIPLimit }})</h3>\n            <div class=\"toolbar\">\n              <label>Show</label>\n              <select class=\"input\" v-model.number=\"vhostTopIPLimit\" title=\"How many top IPs to list\">\n                <option :value=\"25\">25</option>\n                <option :value=\"50\">50</option>\n                <option :value=\"100\">100</option>\n              </select>\n              <label>Block TTL</label>\n              <select class=\"input\" v-model=\"blockTTL\" title=\"TTL used by the Block buttons ('permanent' asks for confirmation)\">\n                <option v-for=\"c in blockTTLChoices\" :key=\"c.label\" :value=\"c.value\">{{ c.label }}</option>\n              </select>\n            </div>\n            <table class=\"mini-table\">\n              <thead><tr><th class=\"checkbox-cell\"><input type=\"checkbox\" :checked=\"allRowsSelected(visibleTopIPRows, 'key')\" @change=\"toggleSelectAllRows(visibleTopIPRows, 'key')\" title=\"Select/unselect all listed IPs\" /></th><th>IP</th><th>Count</th><th>CC</th><th>ASN</th><th>Company</th><th>Action</th></tr></thead>\n              <tbody>\n                <tr v-for=\"ipRow in visibleTopIPRows\" :key=\"ipRow.key\" :class=\"{ 'bulk-selected': isIPSelected(ipRow.key) }\">\n                  <td class=\"checkbox-cell\"><input type=\"checkbox\" :checked=\"isIPSelected(ipRow.key)\" @change=\"toggleIPSelected(ipRow.key)\" /></td>\n                  <td><code>{{ ipRow.key }}</code></td>\n                  <td>{{ ipRow.count }}</td>\n                  <td><span class=\"quick-select\" v-if=\"ipRow.country && ipRow.country !== '-'\" @click=\"selectRowsMatching(visibleTopIPRows, 'key', 'country', ipRow.country)\" :title=\"'Select all listed IPs from ' + ipRow.country\">{{ ipRow.country }}</span><span v-else>{{ ipRow.country }}</span></td>\n                  <td><span class=\"quick-select\" v-if=\"ipRow.asn && ipRow.asn !== '-'\" @click=\"selectRowsMatching(visibleTopIPRows, 'key', 'asn', ipRow.asn)\" :title=\"'Select all listed IPs of ' + ipRow.asn\">{{ ipRow.asn }}</span><span v-else>{{ ipRow.asn }}</span></td>\n                  <td class=\"truncate\" :title=\"ipRow.company\"><span class=\"quick-select\" v-if=\"ipRow.company && ipRow.company !== '-'\" @click=\"selectRowsMatching(visibleTopIPRows, 'key', 'company', ipRow.company)\">{{ ipRow.company }}</span><span v-else>{{ ipRow.company }}</span></td>\n                  <td>\n                    <button class=\"btn-danger\" @click=\"blockIP(ipRow.key)\">Block {{ blockTTLLabel }}</button>\n                    <button class=\"btn-quiet\" @click=\"historyForIP(ipRow.key)\">History</button>\n                  </td>\n                </tr>\n              </tbody>\n            </table>\n            <div class=\"bulkbar\" v-if=\"selectedIPCount\">\n              <strong>{{ selectedIPCount }} IP(s) selected</strong>\n              <button class=\"btn-danger\" :disabled=\"bulkBusy\" @click=\"bulkBlockSelected\">Block selected ({{ blockTTLLabel }})</button>\n              <button class=\"btn-quiet\" :disabled=\"bulkBusy\" @click=\"clearIPSelection\">Clear selection</button>\n              <span class=\"muted\" v-if=\"bulkProgress\">{{ bulkProgress }}</span>\n            </div>\n          </section>\n\n          <section class=\"mini-card path-card\" v-if=\"topPaths.length\">\n            <h3>Top paths ({{ vhostTopPathLimit }})</h3>\n            <table class=\"mini-table\">\n              <thead><tr><th>Path</th><th>Count</th></tr></thead>\n              <tbody>\n                <tr v-for=\"p in topPaths.slice(0, vhostTopPathLimit)\" :key=\"p.key\"><td><code>{{ p.key }}</code></td><td>{{ p.count }}</td></tr>\n              </tbody>\n            </table>\n          </section>\n\n          <section class=\"mini-card agent-card\" v-if=\"topAgents.length\">\n            <h3>Top user-agents</h3>\n            <table class=\"mini-table compact-table\">\n              <thead><tr><th>User-Agent</th><th>Count</th></tr></thead>\n              <tbody>\n                <tr v-for=\"a in topAgents.slice(0, 6)\" :key=\"a.key\"><td>{{ a.key }}</td><td>{{ a.count }}</td></tr>\n              </tbody>\n            </table>\n          </section>\n        </div>\n\n        <details class=\"raw-json\" v-if=\"shortDetail\">\n          <summary>Raw JSON (for debugging)</summary>\n          <pre>{{ rawDrilldownPretty }}</pre>\n        </details>\n        <pre v-else>Select a host to load drilldown details.</pre>\n      </section>",
  history: "<section class=\"card wide\" id=\"history-card\" v-if=\"shouldShow('history')\">\n        <h2>Webdetector history (last 24h)</h2>\n        <div class=\"toolbar\">\n          <label>Host</label>\n          <input class=\"input input-wide\" type=\"text\" v-model.trim=\"historyHost\" placeholder=\"example.com\" list=\"cfm-vhost-list\" />\n          <datalist id=\"cfm-vhost-list\"><option v-for=\"h in knownVhosts\" :key=\"h\" :value=\"h\"></option></datalist>\n          <label>IP</label>\n          <input class=\"input\" type=\"text\" v-model.trim=\"historyIP\" placeholder=\"1.2.3.4\" />\n          <label>Type</label>\n          <select class=\"input\" v-model=\"historyType\" @change=\"refreshHistory\">\n            <option value=\"\">(all)</option>\n            <option value=\"waf_trigger\">waf_trigger</option>\n            <option value=\"waf_observe\">waf_observe</option>\n            <option value=\"challenge_issued\">challenge_issued</option>\n            <option value=\"challenge_solved\">challenge_solved</option>\n            <option value=\"challenge_v2_reject\">challenge_v2_reject</option>\n            <option value=\"challenge_expired_unsolved\">challenge_expired_unsolved</option>\n            <option value=\"block_trigger\">block_trigger</option>\n          </select>\n          <label class=\"muted\" title=\"Show only solves whose User-Agent contradicts itself\"><input type=\"checkbox\" v-model=\"historyOnlyImpossibleUA\" /> impossible UA only</label>\n          <button class=\"btn-quiet\" @click=\"refreshHistory\">Load history</button>\n          <button class=\"btn-quiet\" :disabled=\"historyBusy\" @click=\"pruneHistory(30)\">Prune 30d</button>\n          <button class=\"btn-danger\" :disabled=\"historyBusy\" @click=\"truncateHistory\">Truncate</button>\n        </div>\n        <div class=\"muted\" v-if=\"historySummary\">\n          total={{ historySummary.total_events || 0 }} |\n          issued={{ historySummary.challenge_issued || 0 }} |\n          solved={{ historySummary.challenge_solved || 0 }} |\n          unsolved_expired={{ historySummary.challenge_expired_unsolved || 0 }} |\n          block_triggers={{ historySummary.block_triggers || 0 }} |\n          waf={{ historySummary.waf_observed || 0 }}\n        </div>\n        <div class=\"muted\" v-if=\"historyStats\">\n          db={{ historyStats.path || '-' }} |\n          events={{ historyStats.events || 0 }} |\n          hosts={{ historyStats.unique_hosts || 0 }} |\n          ips={{ historyStats.unique_ips || 0 }} |\n          size={{ formatBytes(historyStats.size_bytes) }} |\n          retention_days={{ historyStats.retention_days }} |\n          prune_every_sec={{ historyStats.prune_every_sec }}\n        </div>\n        <div class=\"table-wrap\">\n          <table>\n            <thead>\n              <tr><th>TS</th><th>Type</th><th>Host</th><th>IP</th><th>CC/ASN</th><th>Reason</th><th>Solve</th><th>UA</th></tr>\n            </thead>\n            <tbody>\n              <tr v-for=\"row in historyEvents\" :key=\"`h-${row.id}-${row.ts_unix}`\">\n                <td :title=\"row.ts_utc || ''\">{{ agoTs(row.ts_unix) }}</td>\n                <td><code>{{ row.event_type }}</code></td>\n                <td>{{ row.host || '-' }}</td>\n                <td><code>{{ row.ip || '-' }}</code></td>\n                <td class=\"truncate\" :title=\"row.asn_name || ''\">{{ row.country || '-' }}<span class=\"muted\" v-if=\"row.asn\"> AS{{ row.asn }}</span></td>\n                <td class=\"truncate\" :title=\"row.reason || '-'\">{{ row.reason || '-' }}</td>\n                <td :title=\"historySolveTitle(row)\">{{ historySolveMs(row) }}</td>\n                <td class=\"truncate\" :title=\"historyForensicsTitle(row)\"><span class=\"pill danger\" v-if=\"row.payload && row.payload.ua_impossible\" :title=\"row.payload.ua_impossible\">impossible</span> {{ (row.payload && row.payload.ua) || '-' }}</td>\n              </tr>\n              <tr v-if=\"!historyEvents.length\"><td colspan=\"8\" class=\"muted\">No history rows yet.</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </section>",
  wafengine: "<section class=\"card wide\" v-if=\"shouldShow('wafengine')\">\n        <h2>WAF engine analytics</h2>\n        <p class=\"muted\">Structured WAF observations from history storage (no raw log parsing in browser). Filters apply to totals, top lists AND the event table.</p>\n        <div class=\"toolbar wrap\">\n          <label>Window (hours)</label>\n          <input class=\"input input-small\" type=\"number\" min=\"1\" max=\"720\" step=\"1\" v-model.number=\"wafHours\" @change=\"refreshWAFEngine\" />\n          <label>Recent events</label>\n          <input class=\"input input-small\" type=\"number\" min=\"1\" max=\"2000\" step=\"1\" v-model.number=\"wafEventLimit\" @change=\"refreshWAFEngine\" />\n          <label>Top N</label>\n          <input class=\"input input-small\" type=\"number\" min=\"1\" max=\"100\" step=\"1\" v-model.number=\"wafTopN\" @change=\"refreshWAFEngine\" />\n          <label for=\"waf-country\">Country</label>\n          <input id=\"waf-country\" class=\"input\" type=\"text\" v-model.trim=\"wafCountry\" placeholder=\"CN, RU\" @keyup.enter=\"refreshWAFEngine\" title=\"Comma-separated ISO codes\" />\n          <label for=\"waf-rule\">Rule</label>\n          <input id=\"waf-rule\" class=\"input input-wide\" type=\"text\" v-model.trim=\"wafRule\" placeholder=\"WAF_SQLI\" @keyup.enter=\"refreshWAFEngine\" title=\"Substring match on rule / rule family\" />\n          <button class=\"btn-quiet\" @click=\"refreshWAFEngine\">Apply</button>\n          <button class=\"btn-quiet\" v-if=\"wafCountry || wafRule\" @click=\"clearWAFFilters\">Clear filters</button>\n        </div>\n        <p v-if=\"actionMsg\" class=\"statusline\">{{ actionMsg }}</p>\n        <div v-if=\"wafSummary\">\n          <p class=\"muted\">\n            total={{ wafSummary.total_events || 0 }}, blocked={{ wafSummary.blocked_events || 0 }},\n            unique hosts={{ wafSummary.unique_hosts || 0 }}, unique IPs={{ wafSummary.unique_ips || 0 }}\n            <span class=\"pill warn\" v-if=\"wafCountry || wafRule\">filtered: {{ [wafRule, wafCountry].filter(Boolean).join(' + ') }}</span>\n          </p>\n          <section class=\"mini-card\" v-show=\"(wafSummary.histogram || []).some(b => b.count > 0)\" style=\"margin-bottom:.7rem\">\n            <h3>Hits per hour <span class=\"top-hint\">follows the active filters</span></h3>\n            <div id=\"waf-hist-chart\" class=\"echart-box\" style=\"width:100%;height:180px\"></div>\n          </section>\n          <div class=\"grid two\">\n            <div>\n              <h3>Top rule families <span class=\"top-hint\">(click to filter)</span></h3>\n              <ul>\n                <li v-for=\"row in (wafSummary.top_rule_bases || [])\" :key=\"`rb-${row.key}`\"><span class=\"quick-select\" @click=\"setWAFRuleFilter(row.key)\">{{ row.key }}</span> \u2014 {{ row.count }}</li>\n              </ul>\n            </div>\n            <div>\n              <h3>Top exact rules <span class=\"top-hint\">(click to filter)</span></h3>\n              <ul>\n                <li v-for=\"row in (wafSummary.top_rules || [])\" :key=\"`r-${row.key}`\"><span class=\"quick-select\" @click=\"setWAFRuleFilter(row.key)\">{{ row.key }}</span> \u2014 {{ row.count }}</li>\n              </ul>\n            </div>\n            <div>\n              <h3>Top countries <span class=\"top-hint\">(click to filter)</span></h3>\n              <ul>\n                <li v-for=\"row in (wafSummary.top_countries || [])\" :key=\"`cc-${row.key}`\"><span class=\"quick-select\" @click=\"setWAFCountryFilter(row.key)\">{{ row.key }}</span> \u2014 {{ row.count }}</li>\n                <li v-if=\"!(wafSummary.top_countries || []).length\" class=\"muted\">no country data</li>\n              </ul>\n            </div>\n            <div>\n              <h3>Top attacked hosts</h3>\n              <ul>\n                <li v-for=\"row in (wafSummary.top_hosts || [])\" :key=\"`h-${row.key}`\">{{ row.key }} \u2014 {{ row.count }}</li>\n              </ul>\n            </div>\n            <div>\n              <h3>Top source IPs</h3>\n              <ul>\n                <li v-for=\"row in (wafSummary.top_ips || [])\" :key=\"`ip-${row.key}`\">\n                  <div><code>{{ row.key }}</code> \u2014 {{ row.count }}</div>\n                  <div class=\"muted\" v-if=\"row.ptr || row.country || row.asn || row.asn_name\">\n                    {{ row.ptr || '-' }} | <span class=\"quick-select\" v-if=\"row.country\" @click=\"setWAFCountryFilter(row.country)\">{{ row.country }}</span><span v-else>-</span>{{ row.asn ? (' | AS' + row.asn) : '' }}{{ row.asn_name ? (' ' + row.asn_name) : '' }}\n                  </div>\n                </li>\n              </ul>\n            </div>\n          </div>\n          <div class=\"table-wrap\">\n            <table>\n              <thead>\n                <tr><th>Time</th><th>Host</th><th>IP</th><th>Method</th><th>URI</th><th>Status</th><th>Rule</th><th>CC/ASN</th><th>Actions</th></tr>\n              </thead>\n              <tbody>\n                <tr v-for=\"(row, idx) in (wafSummary.rows || [])\" :key=\"`${row.ts_unix}-${row.ip}-${idx}`\">\n                  <td :title=\"fmtTs(row.ts_unix)\">{{ agoTs(row.ts_unix) }}</td>\n                  <td>{{ row.host || '-' }}</td>\n                  <td><code>{{ row.ip }}</code></td>\n                  <td>{{ row.method || '-' }}</td>\n                  <td class=\"truncate\" :title=\"row.uri\">{{ row.uri || '-' }}</td>\n                  <td>{{ row.status || '-' }}</td>\n                  <td class=\"truncate\"><span class=\"quick-select\" :title=\"row.reason\" @click=\"setWAFRuleFilter(row.rule_base || row.reason)\">{{ row.reason || '-' }}</span></td>\n                  <td class=\"truncate\" :title=\"row.asn_name\"><span class=\"quick-select\" v-if=\"row.country\" @click=\"setWAFCountryFilter(row.country)\">{{ row.country }}</span><span v-else>-</span> {{ row.asn ? ('AS' + row.asn) : '' }}</td>\n                  <td class=\"actions-cell\">\n                    <button class=\"btn-quiet btn-sm\" @click=\"historyForIP(row.ip)\">History</button>\n                    <button class=\"btn-quiet btn-sm\" v-if=\"row.host\" @click=\"quickWAFExclude('host', row.host)\" title=\"False positive? Disable the WAF for this vhost via a host exclude.\">Excl host</button>\n                    <button class=\"btn-quiet btn-sm\" v-if=\"row.uri\" @click=\"quickWAFExclude('path', uriPath(row.uri))\" :title=\"'False positive? Exclude this path from the WAF: ' + uriPath(row.uri)\">Excl path</button>\n                  </td>\n                </tr>\n                <tr v-if=\"!(wafSummary.rows || []).length\"><td colspan=\"9\" class=\"muted\">No WAF events in selected window{{ (wafCountry || wafRule) ? ' matching the filters' : '' }}.</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>",
  ipdrilldown: "<section class=\"card wide\" v-if=\"shouldShow('ipdrilldown')\">\n        <h2>IP drilldown</h2>\n        <p class=\"muted\" v-if=\"activeIP\">Drilldown for IP: <strong>{{ activeIP }}</strong></p>\n        <div class=\"table-wrap\" v-if=\"ipDrilldown && Array.isArray(ipDrilldown.hosts)\">\n          <table>\n            <thead><tr><th>Host</th><th>Req</th><th>Action</th></tr></thead>\n            <tbody>\n              <tr v-for=\"h in ipDrilldown.hosts.slice(0, 20)\" :key=\"h.key\" class=\"clickable\" @click=\"openVhostLive(h.key)\">\n                <td>{{ h.key }}</td><td>{{ h.count }}</td><td><button class=\"btn-quiet\" @click.stop=\"historyForHost(h.key)\">History</button></td>\n              </tr>\n              <tr v-if=\"!ipDrilldown.hosts.length\"><td colspan=\"3\" class=\"muted\">No host rows for this IP.</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <details class=\"raw-json\" v-if=\"ipDrilldown\">\n          <summary>Raw JSON (IP drilldown)</summary>\n          <pre>{{ rawIPDrilldownPretty }}</pre>\n        </details>\n      </section>",
  analyze: "<section class=\"card wide\" v-if=\"shouldShow('analyze')\">\n        <h2>Analyze (offline TSV)</h2>\n        <div class=\"toolbar\">\n          <label for=\"analyze-target\">Target</label>\n          <input id=\"analyze-target\" class=\"input input-wide\" type=\"text\" v-model.trim=\"analyzeTarget\" placeholder=\"IP or vhost\" />\n          <label for=\"analyze-last\">Last</label>\n          <input id=\"analyze-last\" class=\"input\" type=\"text\" v-model.trim=\"analyzeLast\" placeholder=\"last, e.g. 30m or 1h\" />\n          <button class=\"btn-quiet\" :disabled=\"analyzeLoading\" @click=\"runAnalyze('ip')\">Analyze IP</button>\n          <button class=\"btn-quiet\" :disabled=\"analyzeLoading\" @click=\"runAnalyze('host')\">Analyze host</button>\n        </div>\n        <pre v-if=\"analyzeResult\">{{ rawAnalyzePretty }}</pre>\n        <p v-else class=\"muted\">Run analyze-ip / analyze-host directly from UI.</p>\n      </section>",
};

export function expandPartials(root = document) {
  root.querySelectorAll("[data-wd-section]").forEach((el) => {
    const name = el.getAttribute("data-wd-section");
    const html = PARTIALS[name];
    if (!html) {
      console.error("[cfm-webui] unknown section partial:", name);
      return;
    }
    const tpl = document.createElement("template");
    tpl.innerHTML = html;
    el.replaceWith(tpl.content);
  });
}
